#!/usr/bin/env node
/**
 * Capture admin data-entry forms for every collection — shows the new
 * fields added during the recent session (OIB, licence number, city,
 * specialty areas, language pairs, court affiliation, etc.).
 *
 * Requires .admin-state.json (generated by admin-login.mjs). Without it
 * the script exits early with instructions.
 *
 * For each collection it captures TWO shots:
 *   <NN>a-<slug>-table.png  — the listing table with column headers
 *   <NN>b-<slug>-edit.png   — the edit form opened on the first row
 *                              (shows all fields, including the new ones)
 *
 * Plus a 'create new' form for one collection (judges) to show the
 * blank state for documentation.
 */
import { chromium } from 'playwright'
import { mkdirSync, writeFileSync, existsSync } from 'node:fs'
import { join } from 'node:path'

const BASE = process.env.BASE_URL || 'http://23.164.48.64'
const STATE_FILE = process.env.STATE_FILE || join(import.meta.dirname || '.', '.admin-state.json')

if (!existsSync(STATE_FILE)) {
  console.error(`
Auth state not found: ${STATE_FILE}

Run this once first to log in interactively:
  node tests/e2e/admin-login.mjs

Then re-run this script.`)
  process.exit(1)
}

const today = new Date().toISOString().slice(0, 10)
const OUT_DIR = process.env.OUT_DIR || `docs/screenshots/${today}-admin`
mkdirSync(OUT_DIR, { recursive: true })

// Collections to capture. Order matches admin sidebar.
const COLLECTIONS = [
  { slug: 'judges',                       label: 'Judges — added court relation + appointment date + specialization' },
  { slug: 'expert-witnesses',             label: 'Expert Witnesses — added specialty areas (array), languages, company, county' },
  { slug: 'interpreters',                 label: 'Interpreters — added language pairs (array), company, county, verified' },
  { slug: 'state-attorneys',              label: 'State Attorneys — added address, city, county, contact' },
  { slug: 'bankruptcy-administrators',    label: 'Bankruptcy Administrators — added OIB, licence number, courts relation' },
  { slug: 'bankruptcy-debtors',           label: 'Bankruptcy Debtors — added OIB, address, contact, notes' },
  { slug: 'courts',                       label: 'Courts — added president, city, county, fax, website, notes' },
  { slug: 'documents',                    label: 'Documents — added category, language, published date' },
  { slug: 'laws',                         label: 'Laws — added year, official gazette (NN), category, effective date, summary' },
  { slug: 'pages',                        label: 'Pages — added meta title/description, language, slug' },
  { slug: 'api-keys',                     label: 'API Keys — added rate limit, organization, active flag' },
]

console.log(`base:  ${BASE}`)
console.log(`out:   ${OUT_DIR}`)
console.log(`shots: ${COLLECTIONS.length * 2 + 1}`)

const browser = await chromium.launch()
const ctx = await browser.newContext({
  viewport: { width: 1440, height: 900 },
  ignoreHTTPSErrors: true,
  storageState: STATE_FILE,
})
const page = await ctx.newPage()

const manifest = []
let ok = 0, fail = 0
let n = 1

async function shot(file, label, extra = {}) {
  const path = join(OUT_DIR, `${file}.png`)
  try {
    await page.screenshot({ path, fullPage: true })
    console.log(`  ✓ ${file}  ${label.slice(0, 60)}`)
    manifest.push({ file: file + '.png', label, ...extra })
    ok++
  } catch (e) {
    console.log(`  ✗ ${file}  ${e.message.slice(0, 80)}`)
    manifest.push({ file: file + '.png', label, error: e.message })
    fail++
  }
}

for (const c of COLLECTIONS) {
  const id = String(n).padStart(2, '0')
  const url = `${BASE}/hr/admin/${c.slug}`

  // ── Table view ──
  try {
    await page.goto(url, { waitUntil: 'networkidle', timeout: 20000 })
    await page.waitForTimeout(1000)
  } catch (e) {
    console.log(`  ✗ ${c.slug} table nav: ${e.message.slice(0, 60)}`)
    fail++
    n++
    continue
  }
  await shot(`${id}a-${c.slug}-table`, `${c.label} — table view`, { url: `/hr/admin/${c.slug}` })

  // ── Edit form (click first row) ──
  try {
    // The row is a <tr role="button"> inside the table body.
    const firstRow = page.locator('table tbody tr').first()
    if (await firstRow.count() > 0) {
      await firstRow.click()
      // Wait for the form (header includes 'Edit #' or 'Create new').
      await page.waitForSelector('form h3:has-text("Edit"), form h3:has-text("Create")', { timeout: 8000 })
      await page.waitForTimeout(500)
      await shot(`${id}b-${c.slug}-edit`, `${c.label} — edit form with new fields`, { url: `/hr/admin/${c.slug}#edit` })
    } else {
      console.log(`  (skip ${c.slug} edit — no rows in table)`)
    }
  } catch (e) {
    console.log(`  ✗ ${c.slug} edit form: ${e.message.slice(0, 60)}`)
    fail++
  }
  n++
}

// Bonus: blank 'Create new' form for judges so the new-record UX is captured too.
try {
  await page.goto(`${BASE}/hr/admin/judges`, { waitUntil: 'networkidle', timeout: 20000 })
  await page.waitForTimeout(800)
  const newBtn = page.locator('button:has-text("New"), button:has-text("Create"), button:has-text("Novo")').first()
  if (await newBtn.count() > 0) {
    await newBtn.click()
    await page.waitForSelector('form h3:has-text("Create")', { timeout: 5000 })
    await page.waitForTimeout(400)
    await shot(`98-judges-create-new`, `Judges — Create new form (blank state)`, { url: '/hr/admin/judges#new' })
  }
} catch {
  // best effort; not all collections expose a New button in this UI variant
}

await browser.close()

writeFileSync(
  join(OUT_DIR, 'manifest.json'),
  JSON.stringify({ base: BASE, generated: new Date().toISOString(), shots: manifest }, null, 2),
)

console.log(`\nDone — ${ok} ok, ${fail} failed. Output: ${OUT_DIR}/`)
